let isManualScrolling = false;
let scrollTimer = null;
let manualMovePx = 0;
let musicObj = []; 
let currentTime = 0; 
let currentIndex = 0; 
let lastIndex = -1; 
let anim = false; 
let threadId = "frs";
let karaokeTimer = null;
let mcolor = "#fff";
let domData = { 
    ul: document.querySelector(".container ul"), 
    container: document.querySelector(".container") 
};

const hasTime = () => musicObj.some(m => m.time >= 0);

const getMusicIndex = () => {
    let time = currentTime;
    for (let i = 0; i < musicObj.length; i++) {
        if (time < musicObj[i].time) return i - 1;
    }
    return musicObj.length - 1;
};

const syncScrollPosition = () => {
    if (isManualScrolling || !hasTime()) return;
    const items = domData.ul.children;
    let currentLi = items[currentIndex];
    if (!currentLi) return;
    let movePx = currentLi.offsetTop + (currentLi.clientHeight / 2) - (domData.container.clientHeight / 2);
    if (movePx < 0) movePx = 0;
    domData.ul.style.transform = "translateY(-" + movePx + "px)";
};

const updateKaraokeProgress = (idx) => {
    if (idx < 0 || !musicObj[idx] || !musicObj[idx].words || !musicObj[idx].words.length) return;
    const li = domData.ul.children[idx];
    if (!li) return;
    const words = li.querySelectorAll(".karaoke-word");
    const curr = musicObj[idx];
    const start = curr.time * 1000;
    const total = (curr.endTime - curr.time) * 1000;
    const now = currentTime * 1000;
    if (!total || total <= 0) return;
    const lineProgress = Math.min(1, Math.max(0, (now - start) / total));

    curr.words.forEach((w, i) => {
        const ws = (w.o - start) / total;
        const we = ws + (w.d / total);
        let p = 0;
        if (lineProgress >= we) p = 1;
        else if (lineProgress >= ws) p = (lineProgress - ws) / (we - ws);
        if (words[i]) {
            words[i].style.backgroundImage = `linear-gradient(90deg, ${mcolor} ${p * 100}%, #afafaf ${p * 100}%)`;
        }
    });
};

window.addEventListener("wheel", (e) => {
    //if (!hasTime()) return;
    isManualScrolling = true;
    clearTimeout(scrollTimer);
    
    const matrix = new WebKitCSSMatrix(window.getComputedStyle(domData.ul).transform);
    manualMovePx = Math.abs(matrix.m42) + e.deltaY;
    
    const maxMove = domData.ul.clientHeight - domData.container.clientHeight / 2;
    if (manualMovePx < 0) manualMovePx = 0;
    if (manualMovePx > maxMove) manualMovePx = maxMove;

    domData.ul.style.transition = "transform 0.2s ease-out";
    domData.ul.style.transform = "translateY(-" + manualMovePx + "px)";

    scrollTimer = setTimeout(() => {
        isManualScrolling = false;
        domData.ul.style.transition = "transform 0.6s cubic-bezier(0.25, 0.1, 0.2, 1)";
        syncScrollPosition();
    }, 5000);
}, { passive: true });

window.addEventListener("resize", () => {
    syncScrollPosition();
});

const parseKrc = () => {
    let result = []; 
    const emptyLinesCount = 7;
    for (let i = 0; i < emptyLinesCount; i++) { result.push({ time: -1, text: "‎", words: [], isMeta: true }); }
    if (typeof krcData !== "undefined" && krcData.lyric) {
        for (const lineNum in krcData.lyric) {
            const words = krcData.lyric[lineNum];
            if (words.length === 0) continue;
            const startTime = words[0].o / 1000;
            const endTime = (words.at(-1).o + words.at(-1).d) / 1000;
            let lineText = ""; words.forEach(word => lineText += word.text);
            result.push({ 
                time: startTime, 
                endTime: endTime, 
                text: lineText, 
                words: words, 
                isMeta: krcData.lyric[lineNum].isMeta || false 
            });
        }
    }
    return result;
};

const esc = window.lyricEsc || ((s) => String(s));
const createKaraokeLine = (words) => {
    const lineDiv = document.createElement("div"); 
    lineDiv.className = "karaoke-line";
    words.forEach(w => {
        const span = document.createElement("span"); 
        span.className = "karaoke-word";
        const rawText = w.text == null ? "" : String(w.text);
        span.innerHTML = window.lyricRestoreImgTokens ? window.lyricRestoreImgTokens(esc(rawText)) : esc(rawText); 
        span.setAttribute("data-offset", w.o); 
        span.setAttribute("data-duration", w.d);
        lineDiv.appendChild(span);
    });
    return lineDiv;
};

const addMusic = () => {
    let documentFragment = document.createDocumentFragment(); 
    let prevTime = null;
    musicObj.forEach((m) => {
        let li = document.createElement("li");
        let hiddenLine = false;
        if (showMeta === false && m.isMeta) hiddenLine = true;
        else if (showContributors === false && isContributorLine(m.text)) hiddenLine = true;
        if (hiddenLine) li.style.display = "none";
        li.onclick = () => { if (m.time >= 0) window.parent.postMessage({ type: "seekAudio", time: m.time }, "/"); };
        
        let wrapper = document.createElement("div");
        wrapper.className = "lyric-wrapper";
        
        if (m.text === "" || m.time === -1) {
            wrapper.innerHTML = "&nbsp;";
        } else if (m.words && m.words.length > 0) {
            wrapper.appendChild(createKaraokeLine(m.words));
            if(m.translation) { 
                let tDiv = document.createElement("div"); 
                tDiv.className = "trans-line"; 
                tDiv.innerText = m.translation; 
                wrapper.appendChild(tDiv); 
            }
        } else {
            wrapper.innerHTML = window.lyricRestoreImgTokens ? window.lyricRestoreImgTokens(esc(m.text || "")) : esc(m.text || "");
        }
        
        if (prevTime !== null && m.time === prevTime) { li.classList.add("same-line"); }
        prevTime = m.time;
        li.appendChild(wrapper);
        documentFragment.appendChild(li);
    });
    domData.ul.appendChild(documentFragment);
};

const startKaraokeAnimation = (lineIndex) => {
    if (karaokeTimer) { cancelAnimationFrame(karaokeTimer); }
    const allLines = domData.ul.querySelectorAll("li");
    allLines.forEach(line => {
        line.style.color = "#afafaf";
        line.querySelectorAll(".karaoke-word").forEach(w => {
            w.style.backgroundImage = `linear-gradient(90deg, ${mcolor} 0%, #afafaf 0%)`;
        });
    });
    
    if (lineIndex < 0 || lineIndex >= musicObj.length || !musicObj[lineIndex] || !musicObj[lineIndex].words || !musicObj[lineIndex].words.length) return;
    const li = domData.ul.children[lineIndex]; 
    if(!li) return;
    li.style.color = "transparent"; 

    const animate = () => {
        updateKaraokeProgress(currentIndex);
        karaokeTimer = requestAnimationFrame(animate);
    };
    karaokeTimer = requestAnimationFrame(animate);
};

const isCreditRegex = /^(?:作词|作曲|编曲|制作|监制|录音|混音|母带|后期|修音|调校|调教|剪辑|指挥|统筹|录音室|录音棚|助理|抄谱|扒谱|谱务|技师|音控|调音|监听|舞台|灯光|企划|策划|项目|出品|发行|公司|唱片|宣传|宣发|营销|版权|视觉|设计|封面|海报|插画|曲绘|艺术|顾问|题字|文案|翻译|鸣谢|指导|单位|经纪|伴奏|键盘|钢琴|风琴|合成器|采样|序列|吉他|箱琴|尤克里里|贝斯|乌德|班卓|提琴|竖琴|管乐|铜管|木管|笛|萨克斯|小号|长号|大号|打击乐|架子鼓|鼓|定音鼓|铃鼓|钹|锣|沙锤|三角铁|响板|马林巴|古琴|古筝|琵琶|二胡|扬琴|中阮|唢呐|葫芦丝|手风琴|口琴|MIDI|Vocal|Singer|Cover|Performed|Featured|Feat|Ft|Guest|Backing|Chorus|Harmony|Voice|Narration|Dialogue|Rap|Musician|Band|Orchestra|Lyricist|Lyrics|Words|Written|Songwriter|Composer|Composition|Arranger|Arrangement|Producer|Produced|Beatmaker|Programmed|Programming|Directed|Arranged|Engineer|Eng|Mixing|Mixer|Mixed|Mastered|Mst|Editing|Editor|Remix|Supervisor|Manager|Copyist|Transcription|Tech|Publisher|Release|Label|Distributed|Marketing|Promotion|Copyright|Artwork|Image|Photography|Video|PV|MV|Director|Consultant|Thanks|Credits|Solo|Accompaniment)(?:[:：\s\/\-\|]| by)/i;
const isRawJsonMeta = (text) => { try { const t = text.trim(); if (t.startsWith('{') && t.includes('"t"') && t.includes('"c"')) { JSON.parse(t); return true; } } catch(e) {} return false; };
const isContributorLine = (text) => isCreditRegex.test(text.trim());

const matchTranslations = () => {
    if (typeof tlyricData === "undefined" || !tlyricData || tlyricData.length === 0) return;
    let transPool = tlyricData.map(t => ({ ...t, used: false }));
    let potentialPairs = [];
    musicObj.forEach((line, lineIdx) => {
        if (line.time < 0 || line.isMeta) return;
        transPool.forEach((trans, transIdx) => {
            let diff = Math.abs(line.time - trans.time);
            if (diff < 4.0) {
                potentialPairs.push({ lineIdx, transIdx, diff, text: trans.text });
            }
        });
    });
    potentialPairs.sort((a, b) => a.diff - b.diff);
    let matchedLines = new Set();
    let matchedTrans = new Set();
    potentialPairs.forEach(pair => {
        if (matchedLines.has(pair.lineIdx) || matchedTrans.has(pair.transIdx)) return;
        musicObj[pair.lineIdx].translation = pair.text;
        matchedLines.add(pair.lineIdx);
        matchedTrans.add(pair.transIdx);
    });
};

const move = () => {
    if (!hasTime()) return;
    let newIndex = getMusicIndex();
    if (newIndex < 0) newIndex = 0;

    if (newIndex === lastIndex) {
        updateKaraokeProgress(newIndex);
        //syncScrollPosition(); 
        return; 
    }

    const allActives = domData.ul.querySelectorAll(".active, .active-noanim");
    allActives.forEach(el => {
        el.classList.remove("active", "active-noanim");
        el.style.color = "#afafaf";
    });

    lastIndex = newIndex;
    currentIndex = newIndex;

    if (musicObj[newIndex] && musicObj[newIndex].text && musicObj[newIndex].text !== "‎") {
        const report = window.lyricStripImgTokens ? window.lyricStripImgTokens(musicObj[newIndex].text) : musicObj[newIndex].text;
        window.parent.postMessage({ 
            type: "lyricUpdate", 
            text: report.replace(/<[^>]*>?/gm, "").trim() 
        }, "/");
    }

    let currentLi = domData.ul.children[currentIndex];
    if (currentLi) {
        currentLi.classList.add(anim ? "active" : "active-noanim");
        currentLi.style.color = "transparent"; 
        startKaraokeAnimation(currentIndex);
        syncScrollPosition();
    }
};

const findTranslation = (lineTime) => {
    if (lineTime < 0 || typeof tlyricData === "undefined" || !tlyricData || tlyricData.length === 0) return null;
    let closest = null;
    let minDiff = 2.0;
    for (let item of tlyricData) {
        let diff = Math.abs(item.time - lineTime);
        if (diff < minDiff) { minDiff = diff; closest = item.text; }
    }
    return closest;
};

window.addEventListener("message", (e) => { 
    if (e.source !== window.parent) return;
    if (!e.data || typeof e.data !== 'object') return;
    if (e.data.type === "playTimeResponse" && Number.isFinite(Number(e.data.time))) { currentTime = Number(e.data.time); move(); } 
    if (e.data.type === "toggleTrans") { document.body.classList.toggle("show-trans", e.data.visible); }
    if (e.data.type === "updateColor") {
        const c = e.data.color;
        if (typeof c !== 'string' || !/^#[0-9a-fA-F]{3,8}$/.test(c.trim())) return;
        mcolor = c.trim();
        document.documentElement.style.setProperty("--active-color", mcolor);
    }
});

const init = () => {
    musicObj = parseKrc();
    matchTranslations(); 
    addMusic();
    requestAnimationFrame(() => {
        if(!domData.ul.children[0]) return;
        let initialMovePx = domData.container.clientHeight / 2 - domData.ul.children[0].clientHeight / 2;
        domData.ul.style.transition = "none"; 
        domData.ul.style.transform = "translateY(" + initialMovePx + "px)";
        setTimeout(() => { 
            domData.ul.style.transition = "transform 0.6s cubic-bezier(0.25, 0.1, 0.2, 1)"; 
            anim = true; 
        }, 1);
        move();
    });
    setInterval(() => window.parent.postMessage({ type: "getPlayTime", id: threadId }, "/"), 10);
};

init();
window.addEventListener("beforeunload", () => { if (karaokeTimer) cancelAnimationFrame(karaokeTimer); });
window.addEventListener('click', () => { window.parent.postMessage({ type: 'iframeClick' }, '/'); });
